import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.-EXvoMUp.js";const u=JSON.parse('{"title":"Migration notes","description":"","frontmatter":{},"headers":[],"relativePath":"migration.md","filePath":"migration.md"}'),r={name:"migration.md"};function i(s,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="migration-notes" tabindex="-1">Migration notes <a class="header-anchor" href="#migration-notes" aria-label="Permalink to &quot;Migration notes&quot;">​</a></h1><h2 id="existing-default-ids" tabindex="-1">Existing default IDs <a class="header-anchor" href="#existing-default-ids" aria-label="Permalink to &quot;Existing default IDs&quot;">​</a></h2><p>The default unmasked layout stays at 42 timestamp + 12 machine + 5 entropy + 10 random + 12 sequence bits. Existing positive IDs retain their field positions. Earlier documentation described the default as 87 bits; the implemented default is <strong>81 bits</strong>.</p><h2 id="shorter-generator-name" tabindex="-1">Shorter generator name <a class="header-anchor" href="#shorter-generator-name" aria-label="Permalink to &quot;Shorter generator name&quot;">​</a></h2><p>Use <code>import { HID } from &#39;hybrid-id-generator&#39;</code> for the short name. <code>HID</code> is an alias of the existing class, so <code>HID === HybridIDGenerator</code> and existing imports and <code>instanceof</code> checks continue to work. The package name remains <code>hybrid-id-generator</code>.</p><h2 id="correct-imports-and-values" tabindex="-1">Correct imports and values <a class="header-anchor" href="#correct-imports-and-values" aria-label="Permalink to &quot;Correct imports and values&quot;">​</a></h2><p>Use <code>import { HybridIDGenerator } from &#39;hybrid-id-generator&#39;</code> or the equivalent CommonJS named import. <code>nextId()</code> returns <code>HybridID</code>, not a JavaScript number. Use <code>info(id)</code> to inspect fields; there is no <code>decode()</code> method on the generator.</p><p>Decimal strings passed to <code>HybridID</code> now normalize to bigint. <code>valueOf()</code> returns bigint. Negative, blank, and malformed values are rejected instead of being stored unchecked. Numeric equality and ordering no longer depend on whether input was a string or bigint.</p><h2 id="encoding-zero-and-base64-validation" tabindex="-1">Encoding zero and Base64 validation <a class="header-anchor" href="#encoding-zero-and-base64-validation" aria-label="Permalink to &quot;Encoding zero and Base64 validation&quot;">​</a></h2><p>Base32 and Base64 integer zero now encode as <code>A</code>, their first alphabet digit. Older encoders returned <code>0</code>: Base32 rejected it, and Base64 interpreted it as the value 52. There is no safe automatic way to distinguish a legacy Base64 zero from an actual encoded 52. Regenerate legacy zero values from their known decimal source.</p><p>Base64 integer strings of any length now round-trip through <code>HybridID.fromBase64()</code>. Empty strings, invalid digits, and <code>=</code> padding are rejected. These strings are not byte-array Base64.</p><h2 id="clock-changes" tabindex="-1">Clock changes <a class="header-anchor" href="#clock-changes" aria-label="Permalink to &quot;Clock changes&quot;">​</a></h2><p>Monotonic timestamps now use <strong>milliseconds</strong>, consistently with expiry durations. Older monotonic IDs encoded truncated nanoseconds; do not mix those values with the new clock. Retain their old reader or migrate with independently stored creation timestamps. Default wall-clock IDs are unaffected.</p><p>Sequence exhaustion advances logical time by one millisecond. Clock rollback retains the last logical timestamp. Generation no longer busy-waits. Timestamp overflow throws instead of wrapping.</p><h2 id="stricter-configuration" tabindex="-1">Stricter configuration <a class="header-anchor" href="#stricter-configuration" aria-label="Permalink to &quot;Stricter configuration&quot;">​</a></h2><p>Bit widths must be integers in their documented ranges; explicit zero-bit fields are honored. Numeric and environment machine IDs must be integral and in range. Environment values are no longer silently truncated or remapped. Batch size is bounded at 1,000,000. Unknown strategies and invalid expiry durations throw.</p><h2 id="package-and-deployment" tabindex="-1">Package and deployment <a class="header-anchor" href="#package-and-deployment" aria-label="Permalink to &quot;Package and deployment&quot;">​</a></h2><p>The npm package includes built outputs, declarations, README, and license. Use the package root rather than source-tree deep imports. Browser bundlers use the browser ES module; script tags use the new global bundle.</p><p>Documentation source now lives in <code>documentation/</code>, and VitePress generates <code>docs/</code> for GitHub Pages. Legacy Compodoc class/interface links redirect to the matching API pages.</p>',19)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
